def count_triples(n):
    """Counts the number of triples (x, y, z) in {1, ..., n}^3 such that x+y+z is divisible by n."""
    count = 0
    for x in range(1, n + 1):
        for y in range(1, n + 1):
            for z in range(1, n + 1):
                if (x + y + z) % n == 0:
                    count += 1
    return count

